UVM_FILE default_file_handle;

// Stores file handles for specific message IDs
uvm_id_file_array id_file_handles;

// Stores default file handles for each severity level
UVM_FILE severity_file_handles[uvm_severity];
```
```systemverilog
function UVM_FILE get_file_handle(uvm_severity severity, string id);
  UVM_FILE file;

  // First, check if there's a file handle for the specific severity-id combination
  file = get_severity_id_file(severity, id);
  if (file != 0)
    return file;

  // Next, check if there's a file handle for the specific id
  if (id_file_handles.exists(id)) begin
    file = id_file_handles.get(id);
    if (file != 0)
      return file;
  end

  // Then, check if there's a file handle for the specific severity
  if (severity_file_handles.exists(severity)) begin
    file = severity_file_handles[severity];
    if(file != 0)
      return file;
  end

  // If no specific file handle is found, return the default file handle
  return default_file_handle;
endfunction
