function void set_max_quit_count(int count, bit overridable = 1);
  // Check if the max quit count is currently not overridable
  if (max_quit_overridable == 0) begin
    // Report that the max quit count cannot be changed
    uvm_report_info("NOMAXQUITOVR", 
      $sformatf("The max quit count setting of %0d is not overridable to %0d due to a previous setting.", 
      m_max_quit_count, count), UVM_NONE);
    return;
  end

  // Set whether the max quit count can be overridden in the future
  max_quit_overridable = overridable;

  // Set the new max quit count, ensuring it's not negative
  m_max_quit_count = count < 0 ? 0 : count;
endfunction
