从m_stack队尾取scope并清空m_arg

```systemverilog
function void up (byte separator =".");
  bit found;
  string s;
  while(m_stack.size() && !found ) begin
    s = m_stack.pop_back();
    if(separator == ".") begin
      if (s == "" || (s[0] != "[" && s[0] != "(" && s[0] != "{"))
        found = 1;
    end
    else begin
      if(s != "" && s[0] == separator)
        found = 1;
    end
  end
  m_arg = "";
endfunction
