virtual function uvm_queue#(uvm_callback) m_get_tw_cb_q(uvm_object obj);
  // Check if the object is of type T or its derived type
  if(m_am_i_a(obj)) begin
    // Iterate through all derived types of T
    foreach(m_derived_types[i]) begin
      super_type dt;
      // Get the callback object for the derived type
      dt = uvm_typeid_base::typeid_map[m_derived_types[i] ];
      // If a valid derived type is found and it's not the current type
      if(dt != null && dt != this) begin
        // Recursively call m_get_tw_cb_q for the derived type
        m_get_tw_cb_q = dt.m_get_tw_cb_q(obj);
        // If a callback queue is found for the derived type, return it
        if(m_get_tw_cb_q != null)
          return m_get_tw_cb_q;
      end
    end
    // If no derived type matches, return the typewide callback queue for T
    return m_t_inst.m_tw_cb_q;
  end
  else
    // If the object is not of type T or its derived type, return null
    return null;
endfunction
