virtual task generate_stimulus(T t=null, int max_count=0);

  T temp;

  if (t == null)
    t = new;

  for (int i=0; (max_count == 0 || i < max_count) && !m_stop; i++) begin
     if (! t.randomize() )
        uvm_report_warning ("RANDFL", "Randomization failed in generate_stimulus");

